        walls.push(W); mine.push(W);
      }
    }
    if(mine.length&&!bsReach(nav,seen0,b,mine)){
      for(k=walls.length-1;k>=0;k--) if(walls[k].bs&&walls[k].ib===bi) walls.splice(k,1);
      mine=[];
    }
    added+=mine.length;
  }
  return added;
}
